public class Main {
    static int sumDigits(int n) {
        int sum = 0;
        do {
            sum += n % 10;
            n /= 10;
        } while (n > 0);
        return sum;
    }
    public static void main(String[] args) {
        System.out.println(sumDigits(123));
    }
}

