public class Main {
    static int sumNonnegativeEven(int[] a) {
        int sum = 0;
        for (int i = 0; i < a.length; i++) {
            if (a[i] < 0 || a[i] % 2 != 0) continue;
            sum += a[i];
        }
        return sum;
    }
    public static void main(String[] args) {
        System.out.println(sumNonnegativeEven(new int[]{-2, 2, 3}));
    }
}

